/**
 * Supported brand types for the AppLogo component
 * "custom" allows passing a hosted SVG URL via logoUrl
 */
export type AppBrand = "dynamic" | "youtube" | "meta" | "remitly" | "custom";

interface AppLogoProps {
  className?: string;
  /** Brand to display (defaults to "dynamic") */
  brand?: AppBrand;
  /** URL to a hosted logo (used when brand is "custom") */
  logoUrl?: string;
}

/**
 * Configurable App Logo Component
 *
 * Displays the appropriate logo based on the `brand` prop.
 * Defaults to "dynamic" if not specified.
 *
 * Supported values: "dynamic", "youtube", "meta", "remitly", "custom"
 * When brand is "custom", pass a logoUrl to display a hosted image.
 */
export function AppLogo({
  className,
  brand = "dynamic",
  logoUrl,
}: AppLogoProps) {
  switch (brand) {
    case "youtube":
      return <YouTubeStudioLogo className={className} />;
    case "meta":
      return <MetaLogo className={className} />;
    case "remitly":
      return <RemitlyLogo className={className} />;
    case "custom":
      if (logoUrl) {
        // eslint-disable-next-line @next/next/no-img-element
        return <img src={logoUrl} alt="Logo" className={className} />;
      }
      // Fallback to Dynamic logo if no URL provided
      return <DynamicLogo className={className} />;
    case "dynamic":
    default:
      return <DynamicLogo className={className} />;
  }
}
